343	int PhysicsRayCast::rayCastMultiple(const Vec2& origin, const Vec2& end, RayCastHit* outHits, int maxHits)
344	{
345	    Vec2 delta = end - origin;
346	
347	    RayCastInput input;
348	    input.origin = origin;
349	    input.direction = delta;
350	    input.maxDistance = delta.length();
351	    input.categoryMask = _defaultCategoryMask;
352	    input.collisionMask = _defaultCollisionMask;
353	    input.groupFilter = _defaultGroup;
354	
355	    return rayCastAll(input, outHits, maxHits);
