235	bool PhysicsHelper::segmentIntersect(const Vec2& a1, const Vec2& a2, const Vec2& b1, const Vec2& b2, Vec2* intersection)
236	{
237	    const Vec2 r = a2 - a1;
238	    const Vec2 s = b2 - b1;
239	    const float denom = r.cross(s);
240	
241	    if (std::fabs(denom) < kHelperEpsilon)
242	        return false;
243	
244	    const Vec2 d = b1 - a1;
245	    const float t = d.cross(s) / denom;
246	    const float u = d.cross(r) / denom;
247	
248	    if (t < 0.0f || t > 1.0f || u < 0.0f || u > 1.0f)
249	        return false;
250	
251	    if (intersection != nullptr)
252	    {
253	        *intersection = a1 + r * t;
254	    }
255	
256	    return true;
257	}
